/* Pismo opisane przez rodzica; bez analizy dokumentów i bez decyzji o prawie. */
(function(root){
 'use strict';
 const OPTIONS={
  kind:[['request','Wezwanie do uzupełnienia'],['approval','Decyzja przyznająca'],['refusal','Decyzja odmowna'],['notice','Zawiadomienie'],['unknown','Nie wiem jeszcze']],
  decisionScope:[['benefit','Zasiłku — przyznania albo wypłaty'],['insurance','Podlegania ubezpieczeniu'],['unknown','Nie wiem jeszcze']],
  benefit:[['sickness','Chorobowe'],['maternity','Macierzyński'],['parental','Rodzicielski'],['paternity','Ojcowski'],['topup','Podwyższenie do 1000 zł'],['unknown','Nie wiem jeszcze']],
  owner:[['self','Ja'],['payer','Pracodawca lub inny płatnik'],['both','Każda ze stron przygotowuje swoje dokumenty'],['unknown','Nie wiem jeszcze']],
  missingDocument:[['z3','Z-3 — zaświadczenie pracodawcy'],['z3a','Z-3a — zaświadczenie np. zleceniodawcy'],['statement','Moje oświadczenie'],['medical','Zaświadczenie medyczne lub szpitalne'],['zaZyciem','Zaświadczenie „Za życiem”'],['other','Inny dokument wskazany w piśmie'],['unknown','Nie wiem jeszcze']],
  reason:[['noInsurance','Brak ubezpieczenia chorobowego'],['reregistration','Brak ponownego zgłoszenia po przerwie'],['insuranceDecision','Decyzja o niepodleganiu ubezpieczeniu'],['debt','Zadłużenie składkowe / układ ratalny'],['parts','Wykorzystane 5 części rodzicielskiego'],['businessEnded','Zawieszona lub zakończona działalność'],['certificate','Brak właściwego dokumentu'],['other','Inna przyczyna'],['unknown','Nie wiem jeszcze']]
 };
 const TITLES={kind:'Jakie pismo dostałaś lub dostałeś?',decisionScope:'Czego dotyczy sama decyzja?',benefit:'Jakiego świadczenia dotyczy pismo?',deadline:'Jaki termin podano w piśmie?',owner:'Kto ma dostarczyć dokumenty?',missingDocument:'Jakiego dokumentu brakuje?',reason:'Jaką przyczynę wskazuje decyzja?'};
 const HELP={kind:'Wystarczy nazwa rodzaju pisma — nie przepisuj danych ani sygnatury.',decisionScope:'Decyzja o ubezpieczeniu i decyzja o wypłacie zasiłku to odrębne sprawy.',benefit:'Wybierz nazwę z pisma, nawet jeśli jeszcze jej nie rozumiesz.',deadline:'Przepisz datę z pisma lub ustaloną z ZUS; nie liczymy tu terminu odwołania.',owner:'Płatnik to np. pracodawca albo zleceniodawca.',missingDocument:'Wybierz rodzaj dokumentu wymieniony przez ZUS.',reason:'Zaznaczasz treść pisma — Otula nie ocenia słuszności odmowy.'};
 const SOURCES={contact:'https://www.zus.pl/o-zus/kontakt',login:'https://www.zus.pl/ezus/logowanie',forms:'https://www.zus.pl/wzory-formularzy/zasilki/formularze-dla-pracodawcy'};
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')&&+v.slice(0,4)>=1900&&+v.slice(0,4)<2200&&Number.isFinite(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;
 const day=v=>Date.parse(v+'T12:00:00Z');
 const label=(k,v)=>OPTIONS[k]?.find(x=>x[0]===v)?.[1]||'Nie ustalono';
 function sanitize(input={}){const d={};for(const k of Object.keys(OPTIONS))if(OPTIONS[k].some(o=>o[0]===input[k]))d[k]=input[k];if(validDate(input.deadline))d.deadline=input.deadline;else if(input.deadline==='unknown')d.deadline='unknown';if(d.kind!=='refusal')delete d.reason;if(!['approval','refusal'].includes(d.kind))delete d.decisionScope;if(d.kind!=='request'){delete d.owner;delete d.missingDocument;}return d;}
 function questions(input={}){const d=sanitize(input);return ['kind',...(['approval','refusal'].includes(d.kind)?['decisionScope']:[]),'benefit','deadline',...(d.kind==='request'?['owner','missingDocument']:[]),...(d.kind==='refusal'?['reason']:[])];}
 function daysUntil(date,today){const now=today||new Date().toLocaleDateString('sv-SE');return validDate(date)&&validDate(now)?Math.round((day(date)-day(now))/86400000):null;}
 function assess(input={},today){
  const d=sanitize(input),days=daysUntil(d.deadline,today);
  const deadline=days===null?'Sprawdź termin w piśmie':days<0?'Wpisany termin minął — skontaktuj się z ZUS':days===0?'Wpisany termin jest dzisiaj':'Do wpisanego terminu: '+days+' dni';
  let title='Ustal, czego dotyczy pismo',next=['Znajdź tytuł, żądanie i pouczenie w piśmie lub poproś ZUS o wyjaśnienie.'];
  if(d.kind==='request'){title='Przygotuj odpowiedź na wezwanie';next=[label('missingDocument',d.missingDocument),d.owner==='payer'?'Poproś płatnika o przygotowanie i przekazanie jego dokumentu.':d.owner==='both'?'Uzgodnij z płatnikiem podział dokumentów i potwierdzenie przekazania.':d.owner==='self'?'Przygotuj wskazany dokument i podpisz wymagane oświadczenie.':'Sprawdź w piśmie, kto ma przygotować każdy dokument.','Odpowiedz kanałem wskazanym w piśmie: eZUS albo papierowo, i zachowaj potwierdzenie.'];}
  if(d.kind==='approval'){title=d.decisionScope==='insurance'?'Decyzja dotyczy ubezpieczenia':'Sprawdź okres i treść przyznania';next=[d.decisionScope==='insurance'?'Ustalenie ubezpieczenia nie jest jeszcze decyzją o wypłacie zasiłku.':'Porównaj okres, kwotę i adresata decyzji z Twoim wnioskiem.','Odczytaj pouczenie, jeśli nie zgadzasz się z treścią decyzji.'];}
  if(d.kind==='refusal'){title='Sprawdź uzasadnienie i pouczenie';next=[d.decisionScope==='insurance'?'Odmowa dotyczy podlegania ubezpieczeniu — samo dosłanie wniosku o zasiłek nie rozwiązuje tej kwestii.':'Ustal, jakiej części Twojego wniosku dotyczy odmowa.','Sprawdź w pouczeniu tryb, adresata i termin odwołania liczony od doręczenia.','Poproś ZUS o wyjaśnienie wskazanej przyczyny; brak dokumentu można wyjaśnić, lecz nie zapewnia to zmiany decyzji.'];if(d.reason==='debt')next.push('Układ ratalny nie oznacza całkowitej spłaty długu istotnej dla prawa do zasiłku.');if(d.reason==='certificate')next.push('Sprawdź rodzaj wymaganego zaświadczenia; orzeczenie o niepełnosprawności nie zastępuje zaświadczenia „Za życiem”.');}
  if(d.kind==='notice'){title='Sprawdź, czy ZUS oczekuje działania';next=['Odczytaj, czego dotyczy zawiadomienie i czy podano termin odpowiedzi.','Zawiadomienie o postępowaniu nie oznacza samo w sobie przyznania ani odmowy.'];}
  return {title,deadline,days,next,kind:d.kind,scope:d.decisionScope,reportedReason:d.kind==='refusal'?label('reason',d.reason):'',owner:label('owner',d.owner),document:label('missingDocument',d.missingDocument)};
 }
 function requestText(input={},loss=false){const d=sanitize(input);if(loss)return 'Dzień dobry, jestem po stracie i potrzebuję pomocy w formalnościach dotyczących urlopu macierzyńskiego oraz zasiłku. Bardzo proszę o wskazanie osoby, której mogę przekazać dokument potwierdzający stratę, oraz o przygotowanie potrzebnego zaświadczenia płatnika. Proszę też o informację, czy dokumenty wymagają mojego podpisu i jak bezpiecznie je przekazać. Dziękuję za spokojne przeprowadzenie mnie przez te sprawy.';return 'Dzień dobry, otrzymałam/otrzymałem wezwanie z ZUS do uzupełnienia dokumentów. Bardzo proszę o przygotowanie '+(d.missingDocument==='z3a'?'zaświadczenia Z-3a':d.missingDocument==='z3'?'zaświadczenia Z-3':'dokumentów płatnika wskazanych w wezwaniu')+(validDate(d.deadline)?' tak, aby odpowiedź dotarła w terminie do '+d.deadline.split('-').reverse().join('.'):'')+'. Czy mogę prosić o informację, kto przekaże dokumenty do ZUS i o potwierdzenie ich wysłania? Dziękuję za pomoc.';}
 function buildICS(input={},now=new Date()){
  const d=sanitize(input);if(!validDate(d.deadline))throw Error('Najpierw podaj poprawny termin z pisma.');
  const escape=v=>String(v).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
  const stamp=now.toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'');
  const next=new Date(day(d.deadline)+86400000).toISOString().slice(0,10).replace(/-/g,'');
  const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Otula//Termin pisma//PL','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:pismo-'+d.deadline+'-'+(d.kind||'unknown')+'@otula','DTSTAMP:'+stamp,'CLASS:PRIVATE','DTSTART;VALUE=DATE:'+d.deadline.replace(/-/g,''),'DTEND;VALUE=DATE:'+next,'SUMMARY:Sprawdź termin odpowiedzi na pismo','DESCRIPTION:'+escape('Termin wpisany przez Ciebie. Sprawdź pismo oraz sposób przekazania dokumentów. Otula nie wysyła odpowiedzi do urzędu.'),'BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:Sprawdź pismo i przygotuj odpowiedź','TRIGGER:-P1D','END:VALARM','END:VEVENT','END:VCALENDAR'];
  return lines.map(line=>{let out='',part='',bytes=0;for(const ch of line){const n=new TextEncoder().encode(ch).length;if(bytes+n>75){out+=part+'\r\n';part=' ';bytes=1;}part+=ch;bytes+=n;}return out+part;}).join('\r\n')+'\r\n';
 }
 function downloadICS(d){const url=URL.createObjectURL(new Blob([buildICS(d)],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='otula-termin-pisma.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function supportMarkup(){return '<section class="zus-result wywiad-question"><h2>Możesz poprosić o wsparcie</h2><p>Wybierz pomoc, której teraz potrzebujesz.</p><ul class="wywiad-documents"><li><a href="https://ronicpoludzku.com/" target="_blank" rel="noopener noreferrer"><strong>Fundacja Ronić po Ludzku</strong></a><span>Informacje o prawach i wsparciu po stracie ciąży.</span></li><li><a href="https://wczesniak.pl/" target="_blank" rel="noopener noreferrer"><strong>Wcześniak Rodzice–Rodzicom</strong></a><span>Wsparcie rodzin dzieci urodzonych przedwcześnie.</span></li><li><a href="https://rodzicpoludzku.pl/o-nas/kontakt/" target="_blank" rel="noopener noreferrer"><strong>Fundacja Rodzić po Ludzku</strong></a><span>Informacje o prawach w opiece okołoporodowej.</span></li></ul><details><summary>Uprzejma prośba do kadr</summary><p data-copy-text>'+esc(requestText({},true))+'</p><button class="button secondary" type="button" data-copy>Skopiuj prośbę</button><p class="wywiad-message" role="status"></p></details></section>';}
 function bindCopy(container){container.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const box=b.closest('details'),text=box.querySelector('[data-copy-text]').textContent;try{await navigator.clipboard.writeText(text);box.querySelector('[role=status]').textContent='Prośba skopiowana — możesz ją sprawdzić i wysłać.';}catch(e){box.querySelector('[role=status]').textContent='Zaznacz powyższy tekst i skopiuj go ręcznie.';}});}
 function renderLossSupport(container){container.innerHTML=supportMarkup();bindCopy(container);}
 function render(container,ctx={}){
  let data=sanitize(ctx.data),step=ctx.step||questions(data).find(k=>!data[k])||'result';
  const go=next=>{step=next;if(ctx.onNavigate)ctx.onNavigate(next);else draw();};
  const back=()=>{const qs=questions(data),i=qs.indexOf(step);if(step==='result')go(qs.at(-1));else if(i>0)go(qs[i-1]);else if(ctx.onBack)ctx.onBack();else root.location.hash='#moja-sprawa';};
  function answer(key,value){data=sanitize({...data,[key]:value});ctx.onChange?.({...data});const qs=questions(data),i=qs.indexOf(key);go(qs[i+1]||'result');}
  function draw(){
   const qs=questions(data);if(step!=='result'&&!qs.includes(step))step=qs.find(k=>!data[k])||'result';
   container.innerHTML='<section class="zus-page wywiad-page"><button type="button" class="button secondary" data-back>Wróć do: '+(step===qs[0]?'sytuacji':'poprzedniego kroku')+'</button><nav class="breadcrumbs" aria-label="Ścieżka"><a href="#start">Start</a><span> / </span><a href="#moja-sprawa">Moja sprawa</a><span> / Pismo z ZUS</span></nav><div data-body></div></section>';
   container.querySelector('[data-back]').onclick=back;const body=container.querySelector('[data-body]');
   if(step==='result'){
    const r=assess(data);body.innerHTML='<article class="zus-result wywiad-question"><span class="chip lilac">Twoje pismo</span><h1>'+esc(r.title)+'</h1><p>'+esc(label('kind',data.kind))+' · '+esc(label('benefit',data.benefit))+'</p>'+(['approval','refusal'].includes(data.kind)?'<p><strong>Przedmiot:</strong> '+esc(label('decisionScope',data.decisionScope))+'</p>':'')+'<dl class="wywiad-facts"><div><dt>Termin wpisany z pisma</dt><dd>'+esc(r.deadline)+'</dd></div>'+(data.kind==='request'?'<div><dt>Kto przygotowuje</dt><dd>'+esc(r.owner)+'</dd></div>':'')+'</dl><ol>'+r.next.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>'+(r.reportedReason?'<details open><summary>Przyczyna zaznaczona przez Ciebie</summary><p>'+esc(r.reportedReason)+'</p><p>To odczytana przez Ciebie treść pisma, nie ustalenie Otuli.</p></details>':'')+'<div class="case-actions">'+(validDate(data.deadline)?'<button type="button" class="button primary" data-ics>Dodaj termin do kalendarza</button>':'')+'<a class="button secondary" href="'+SOURCES.login+'" target="_blank" rel="noopener noreferrer">Otwórz eZUS</a><a class="button secondary" href="'+SOURCES.contact+'" target="_blank" rel="noopener noreferrer">Kontakt z ZUS</a></div>'+(validDate(data.deadline)?'<p class="wywiad-help">Zaimportuj plik do kalendarza i sprawdź przypomnienie dzień wcześniej; Otula nie wysyła powiadomień w tle.</p>':'')+(data.kind==='request'?'<details><summary>Prośba do kadr i podpisy</summary><p data-copy-text>'+esc(requestText(data))+'</p><button type="button" class="button secondary" data-copy>Skopiuj prośbę</button><p class="wywiad-message" role="status"></p><p>Jeśli ZUS wymaga oświadczenia osoby uprawnionej, skan przesłany z cudzego konta lub przez biuro rachunkowe nie zastępuje jej oświadczenia i wymaganego podpisu.</p><a href="'+SOURCES.forms+'" target="_blank" rel="noopener noreferrer">Aktualne dokumenty płatnika</a></details>':'')+'</article>';body.querySelector('[data-ics]')?.addEventListener('click',()=>downloadICS(data));bindCopy(body);return;
   }
   const current=data[step],i=qs.indexOf(step);body.innerHTML='<article class="zus-result wywiad-question"><p class="small-label">Pismo z ZUS · krok '+(i+1)+' z '+qs.length+'</p><h1>'+esc(TITLES[step])+'</h1><p class="wywiad-help">'+esc(HELP[step])+'</p>'+(step==='deadline'?'<form><label class="wywiad-input"><span>Termin odpowiedzi</span><input name="deadline" type="date" min="1900-01-01" max="2199-12-31" value="'+(validDate(current)?current:'')+'"></label><p class="wywiad-error" role="alert"></p><div class="wywiad-actions"><button type="submit" class="button primary">Dalej</button><button type="button" class="button secondary" data-option="unknown">Nie wiem jeszcze</button></div></form>':'<div class="wywiad-choices">'+OPTIONS[step].map(([v,t])=>'<button type="button" class="button secondary wywiad-choice'+(current===v?' active':'')+'" data-option="'+v+'" aria-pressed="'+(current===v)+'"><span>'+esc(t)+'</span><span class="wywiad-choice-mark" aria-hidden="true">'+(current===v?'✓':'')+'</span></button>').join('')+'</div>')+'</article>';
   body.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>answer(step,b.dataset.option));body.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();const v=e.target.elements.deadline.value;if(!validDate(v)){body.querySelector('[role=alert]').textContent='Wpisz prawidłową datę albo wybierz „Nie wiem jeszcze”.';return;}answer(step,v);});
  }
  draw();return {getData:()=>({...data}),go};
 }
 const api={OPTIONS,SOURCES,sanitize,questions,assess,daysUntil,requestText,buildICS,render,renderLossSupport,supportMarkup};root.OtulaPismo=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window==='undefined'?globalThis:window);
